59	// Forward declaration for multi-threaded collect
60	static void mi_decl_noinline mi_free_try_collect_mt(mi_page_t* page, mi_block_t* mt_free) mi_attr_noexcept;
61	
62	// Free a block multi-threaded
63	static inline void mi_free_block_mt(mi_page_t* page, mi_block_t* block, bool was_guarded, bool allow_collect) mi_attr_noexcept
64	{
65	  size_t usable_size;
66	  if mi_unlikely(!mi_check_padding_on_free(page, block, was_guarded, &usable_size)) return;    // checking padding is safe for mt
67	  
68	  // adjust stats (after padding check )
69	  mi_stat_free(page, block);    // stat_free may access the padding
70	  mi_track_free_size(block, usable_size);
71	
72	  // _mi_padding_shrink(page, block, sizeof(mi_block_t));
73	  #if (MI_DEBUG>0) && !MI_TRACK_ENABLED  && !MI_TSAN       // note: when tracking, cannot use mi_usable_size with multi-threading
74	  if (!was_guarded) {
75	    const size_t dbgsize = (usable_size > MI_MiB ? MI_MiB : usable_size);
76	    _mi_memset_aligned(block, MI_DEBUG_FREED, dbgsize);
77	  }
78	  #endif
79	
80	  // push atomically on the page thread free list
81	  mi_thread_free_t tf_new;
82	  mi_thread_free_t tf_old = mi_atomic_load_relaxed(&page->xthread_free);
83	  do {
84	    mi_block_set_next(page, block, mi_tf_block(tf_old));
85	    const bool new_owned = (allow_collect ? true : mi_tf_is_owned(tf_old));    // if allow collection then always try to claim it if the page is abandoned 
86	    tf_new = mi_tf_create(block, new_owned);
87	  } while (!mi_atomic_cas_weak_acq_rel(&page->xthread_free, &tf_old, tf_new)); // todo: release is enough?
88	
89	  // and atomically try to collect the page if it was abandoned
90	  if (allow_collect) {
91	    const bool is_owned_now = !mi_tf_is_owned(tf_old);
92	    if (is_owned_now) {
93	      mi_assert_internal(mi_page_is_abandoned(page));
94	      mi_free_try_collect_mt(page,block);
95	    }
96	  }
97	}
